/* eslint-disable @typescript-eslint/no-explicit-any */
'use client'

import { useEditor, EditorContent } from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import Placeholder from '@tiptap/extension-placeholder'
// import Underline from '@tiptap/extension-underline'
import TextAlign from '@tiptap/extension-text-align'
import FontFamily from '@tiptap/extension-font-family'
import { TextStyle } from '@tiptap/extension-text-style' //  Add this
import { useEffect } from 'react'

// Toolbar component
const Toolbar = ({ editor }: { editor: any }) => {
  if (!editor) return null

  return (
    <div className="border border-[#B6B6B6] border-b-0 rounded-t-md p-2 flex flex-wrap gap-1">
      {/* Heading dropdown */}
      <select
        onChange={(e) =>
          e.target.value
            ? editor
                .chain()
                .focus()
                .setHeading({ level: parseInt(e.target.value) as 1 | 2 | 3 })
                .run()
            : editor.chain().focus().setParagraph().run()
        }
        value={editor.getAttributes('heading').level || ''}
        className="border rounded p-1"
      >
        <option value="">Paragraph</option>
        <option value="1">Heading 1</option>
        <option value="2">Heading 2</option>
        <option value="3">Heading 3</option>
      </select>

      {/* Font family dropdown */}
      <select
        onChange={(e) =>
          editor.chain().focus().setFontFamily(e.target.value).run()
        }
        className="border rounded p-1"
      >
        <option value="">Font</option>
        <option value="Arial">Arial</option>
        <option value="Georgia">Georgia</option>
        <option value="Times New Roman">Times New Roman</option>
        <option value="Courier New">Courier New</option>
      </select>

      {/* Bold */}
      <button
        onClick={() => editor.chain().focus().toggleBold().run()}
        className={`p-1 rounded ${
          editor.isActive('bold') ? 'bg-gray-200' : ''
        }`}
      >
        <strong>B</strong>
      </button>

      {/* Italic */}
      <button
        onClick={() => editor.chain().focus().toggleItalic().run()}
        className={`p-1 rounded ${
          editor.isActive('italic') ? 'bg-gray-200' : ''
        }`}
      >
        <em>I</em>
      </button>

      {/* Underline */}
      <button
        onClick={() => editor.chain().focus().toggleUnderline().run()}
        className={`p-1 rounded ${
          editor.isActive('underline') ? 'bg-gray-200' : ''
        }`}
      >
        <u>U</u>
      </button>

      {/* Alignment */}
      <select
        onChange={(e) =>
          editor.chain().focus().setTextAlign(e.target.value).run()
        }
        className="border rounded p-1"
      >
        <option value="left">Left</option>
        <option value="center">Center</option>
        <option value="right">Right</option>
        <option value="justify">Justify</option>
      </select>

      {/* Ordered list */}
      <button
        onClick={() => editor.chain().focus().toggleOrderedList().run()}
        className={`p-1 rounded ${
          editor.isActive('orderedList') ? 'bg-gray-200' : ''
        }`}
      >
        OL
      </button>

      {/* Bullet list */}
      <button
        onClick={() => editor.chain().focus().toggleBulletList().run()}
        className={`p-1 rounded ${
          editor.isActive('bulletList') ? 'bg-gray-200' : ''
        }`}
      >
        UL
      </button>

      {/* Code block */}
      <button
        onClick={() => editor.chain().focus().toggleCodeBlock().run()}
        className={`p-1 rounded ${
          editor.isActive('codeBlock') ? 'bg-gray-200' : ''
        }`}
      >
        Code
      </button>
    </div>
  )
}

interface TiptapEditorProps {
  content: string
  onChange: (content: string) => void
}

export default function TiptapEditor({ content, onChange }: TiptapEditorProps) {
  const editor = useEditor({
    extensions: [
      StarterKit,
      Placeholder.configure({
        placeholder: 'Enter product description...',
      }),
      // Underline,
      TextAlign.configure({
        types: ['heading', 'paragraph'],
      }),
      TextStyle, //  Must be included
      FontFamily.configure({
        types: ['textStyle'],
      }),
    ],
    content,
    onUpdate: ({ editor }) => {
      onChange(editor.getHTML())
    },
    immediatelyRender: false,
  })

  useEffect(() => {
    if (editor && content !== editor.getHTML()) {
      editor.commands.setContent(content)
    }
  }, [content, editor])

  return (
    <div className="border border-[#B6B6B6] rounded-md focus-within:border-[#B6B6B6]">
      <Toolbar editor={editor} />
      <EditorContent
        editor={editor}
        className="p-4 min-h-[250px] prose max-w-none [&_.ProseMirror]:outline-none [&_.ProseMirror]:border-none [&_.ProseMirror]:ring-0 [&_.ProseMirror:focus]:outline-none [&_.ProseMirror:focus]:border-none [&_.ProseMirror:focus]:ring-0"
      />
    </div>
  )
}
